			TO security_account [ ,...n ] 
			[ WITH GRANT OPTION ] 
			[ AS { group | role } ] 

			REVOKE [ GRANT OPTION FOR ] 
			    { ALL [ PRIVILEGES ] | permission [ ,...n ] } 
			    { 
			        [ ( column [ ,...n ] ) ] ON { table | view } 
			        | ON { table | view } [ ( column [ ,...n ] ) ] 
			        | ON { stored_procedure | extended_procedure } 
